solution_files.limits.yaml:
{
  "apiVersion": "networking.istio.io/v1alpha3",
  "kind": "EnvoyFilter",
  "metadata": {
    "name": "global-limit",
    "namespace": "mesh-training"
  },
  "spec": {
    "workloadSelector": {
      "labels": {
        "istio": "ingressgateway"
      }
    },
    "configPatches": [
      {
        "applyTo": "HTTP_FILTER",
        "match": {
          "context": "GATEWAY",
          "listener": {
            "filterChain": {
              "filter": {
                "name": "envoy.filters.network.http_connection_manager",
                "subFilter": {
                  "name": "envoy.filters.http.router"
                }
              }
            }
          }
        },
        "patch": {
          "operation": "INSERT_BEFORE",
          "value": {
            "name": "envoy.filters.http.ratelimit",
            "typed_config": {
              "@type": "type.googleapis.com/envoy.extensions.filters.http.ratelimit.v3.RateLimit",
              "domain": "training",
              "failure_mode_deny": true,
              "timeout": "0.25s",
              "rate_limit_service": {
                "grpc_service": {
                  "envoy_grpc": {
                    "cluster_name": "outbound|8081||ratelimit.mesh-training.svc.cluster.local"
                  }
                },
                "transport_api_version": "V3"
              }
            }
          }
        }
      },
      {
        "applyTo": "HTTP_ROUTE",
        "match": {
          "context": "GATEWAY",
          "routeConfiguration": {
            "vhost": {
              "name": "*:8080",
              "route": {
                "name": "api"
              }
            }
          }
        },
        "patch": {
          "operation": "MERGE",
          "value": {
            "route": {
              "rate_limits": [
                {
                  "actions": [
                    {
                      "generic_key": {
                        "descriptor_value": "approved"
                      }
                    }
                  ]
                }
              ]
            }
          }
        }
      }
    ]
  }
}
---
{
  "apiVersion": "v1",
  "kind": "ConfigMap",
  "metadata": {
    "name": "rate-limit-rules",
    "namespace": "mesh-training"
  },
  "data": {
    "config.yaml": "domain: training\ndescriptors:\n- key: generic_key\n  value: approved\n  rate_limit:\n    unit: minute\n    requests_per_unit: 60\n"
  }
}

